from pgmpy.causal_discovery import PC
from pgmpy.estimators.BaseConstraintEstimator import BaseConstraintEstimator
from pgmpy.independencies import Independencies
import pandas as pd
import numpy as np

# Test order independence for stable variant
def fake_ci_t(X, Y, Z=[], **kwargs):
    Z = list(Z)
    if X == 'B':
        if Y == 'C' or Y == 'D':
            return True
        elif Y == 'A' and Z == ['C']:
            return True
    elif X == 'C' and Y == 'D' and Z == []:
        return True
    elif X == 'D' and Y == 'C' and Z == []:
        return True
    elif Y == 'B':
        if X == 'C' or X == 'D':
            return True
        elif X == 'A' and Z == ['C']:
            return True
    elif X == 'A' and Y == 'C' and Z == ['B']:
        return True
    elif X == 'C' and Y == 'A' and Z == ['B']:
        return True
    return False

np.random.seed(42)
fake_data = pd.DataFrame(np.random.random((1000, 4)), columns=['A', 'B', 'C', 'D'])

# Run stable multiple times with different column orderings and compare skeletons
results = []
for cols in [['A', 'B', 'C', 'D'], ['D', 'C', 'B', 'A'], ['B', 'A', 'D', 'C']]:
    data = fake_data[cols]
    skel, sepsets = PC()._build_skeleton(data, ci_test=fake_ci_t, variant='stable', show_progress=False)
    edges = frozenset(frozenset(e) for e in skel.edges())
    results.append(edges)
    print('cols', cols, 'edges', edges)

assert len(set(results)) == 1, 'Stable variant should be order-independent'
print('Order independence check passed')
""}

